Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
wifi: wilc1000: fix u8 overflow in SSID scan buffer size
 calculation

The variable valuesize is declared as u8 but accumulates the total
length of all SSIDs to scan. Each SSID contributes up to 33 bytes
(IEEE80211_MAX_SSID_LEN + 1), and with WILC_MAX_NUM_PROBED_SSID (10)
SSIDs the total can reach 330, which wraps around to 74 when stored
in a u8.

This causes kmalloc to allocate only 75 bytes while the subsequent
memcpy writes up to 331 bytes into the buffer, resulting in a 256-byte
heap buffer overflow.

Widen valuesize from u8 to u32 to accommodate the full range.

Fixes: c5c77ba18ea6 ("staging: wilc1000: Add SDIO/SPI 802.11 driver")
Cc: stable@vger.kernel.org
Signed-off-by: Yasuaki Torimaru <yasuakitorimaru@gmail.com>
Link: https://patch.msgid.link/20260324100624.983458-1-yasuakitorimaru@gmail.com
Signed-off-by: Johannes Berg <johannes.berg@intel.com>

Here is the root cause:
Use of a u8 variable (`valuesize`) to accumulate the total length of all SSIDs to scan, each SSID up to 33 bytes and up to 10 SSIDs (max 330 bytes). This causes integer overflow (wrapping to 74), leading to kmalloc allocating only 75 bytes while subsequent memcpy writes up to 331 bytes, resulting in a heap buffer overflow.

Here is the patch:

 int wilc_scan(struct wilc_vif *vif, u8 scan_source,
 	      u8 scan_type, u8 *ch_freq_list,
 	      void (*scan_result_fn)(enum scan_event,
 				     struct wilc_rcvd_net_info *,
 				     struct wilc_priv *),
 	      struct cfg80211_scan_request *request)
 {
 	int result = 0;
 	struct wid wid_list[WILC_SCAN_WID_LIST_SIZE];
 	u32 index = 0;
 	u32 i, scan_timeout;
 	u8 *buffer;
-	u8 valuesize = 0;
+	u32 valuesize = 0;
 	u8 *search_ssid_vals = NULL;
 	const u8 ch_list_len = request->n_channels;
 	struct host_if_drv *hif_drv = vif->hif_drv;

 	if (hif_drv->hif_state >= HOST_IF_SCANNING &&
 	    hif_drv->hif_state < HOST_IF_CONNECTED) {
 		netdev_err(vif->ndev, "Already scan\n");
 		result = -EBUSY;
 		goto error;
 	}

 	if (vif->connecting) {
 		netdev_err(vif->ndev, "Don't do obss scan\n");
 		result = -EBUSY;
 		goto error;
 	}

 	hif_drv->usr_scan_req.ch_cnt = 0;

 	if (request->n_ssids) {
 		for (i = 0; i < request->n_ssids; i++)
 			valuesize += ((request->ssids[i].ssid_len) + 1);
 		search_ssid_vals = kmalloc(valuesize + 1, GFP_KERNEL);
 		if (search_ssid_vals) {
 			wid_list[index].id = WID_SSID_PROBE_REQ;
 			wid_list[index].type = WID_STR;
 			wid_list[index].val = search_ssid_vals;
 			buffer = wid_list[index].val;

 			*buffer++ = request->n_ssids;

 			for (i = 0; i < request->n_ssids; i++) {
 				*buffer++ = request->ssids[i].ssid_len;
 				memcpy(buffer, request->ssids[i].ssid,
 				       request->ssids[i].ssid_len);
 				buffer += request->ssids[i].ssid_len;
 			}
 			wid_list[index].size = (s32)(valuesize + 1);
 			index++;
 		}
 	}

 	wid_list[index].id = WID_INFO_ELEMENT_PROBE;
 	wid_list[index].type = WID_BIN_DATA;
 	wid_list[index].val = (s8 *)request->ie;
 	wid_list[index].size = request->ie_len;
 	index++;

 	wid_list[index].id = WID_SCAN_TYPE;
 	wid_list[index].type = WID_CHAR;
 	wid_list[index].size = sizeof(char);
 	wid_list[index].val = (s8 *)&scan_type;
 	index++;

 	if (scan_type == WILC_FW_PASSIVE_SCAN && request->duration) {
 		wid_list[index].id = WID_PASSIVE_SCAN_TIME;
 		wid_list[index].type = WID_SHORT;
 		wid_list[index].size = sizeof(u16);
 		wid_list[index].val = (s8 *)&request->duration;
 		index++;

 		scan_timeout = (request->duration * ch_list_len) + 500;
 	} else {
 		scan_timeout = WILC_HIF_SCAN_TIMEOUT_MS;
 	}

 	wid_list[index].id = WID_SCAN_CHANNEL_LIST;
 	wid_list[index].type = WID_BIN_DATA;

 	if (ch_freq_list && ch_list_len > 0) {
 		for (i = 0; i < ch_list_len; i++) {
 			if (ch_freq_list[i] > 0)
 				ch_freq_list[i] -= 1;
 		}
 	}

 	wid_list[index].val = ch_freq_list;
 	wid_list[index].size = ch_list_len;
 	index++;

 	wid_list[index].id = WID_START_SCAN_REQ;
 	wid_list[index].type = WID_CHAR;
 	wid_list[index].size = sizeof(char);
 	wid_list[index].val = (s8 *)&scan_source;
 	index++;

 	hif_drv->usr_scan_req.scan_result = scan_result_fn;
 	hif_drv->usr_scan_req.priv = &vif->priv;

 	result = wilc_send_config_pkt(vif, WILC_SET_CFG, wid_list, index);
 	if (result) {
 		netdev_err(vif->ndev, "Failed to send scan parameters\n");
 		goto error;
 	}

 	hif_drv->scan_timer_vif = vif;
 	mod_timer(&hif_drv->scan_timer,
 		  jiffies + msecs_to_jiffies(scan_timeout));

 error:

 	kfree(search_ssid_vals);

 	return result;
 }



